import re


def eval_expression(expr: str) -> float:
    # Tokenize the expression: numbers (including decimals and negatives), operators, and parentheses
    # We need to handle negative numbers carefully. A '-' is unary if it's at the start or follows an operator/left paren.
    token_pattern = re.compile(
        r"\s*(?:([0-9]+(?:\.[0-9]+)?)|([\+\-\*\/\(\)]))"
    )

    tokens = []
    # Pre-process to handle unary minus by inserting '0' before a leading '-' or a '-' after another operator/paren
    # Or we can handle it directly in the tokenizer/parser.
    # Let's clean the string and tokenize manually for safety.

    # Simple tokenizer
    raw_tokens = re.findall(r"(?:[0-9]+(?:\.[0-9]+)?|\+|\-|\*|\/|\(|\))", expr)

    if not raw_tokens:
        raise ValueError("Empty expression")

    # Handle unary minus by replacing occurrences like ['-', '5'] with ['0', '-', '5']
    tokens = []
    expect_operand = True  # True if we expect a number or unary minus next

    i = 0
    while i < len(raw_tokens):
        token = raw_tokens[i]
        if token in "+-*/":
            if expect_operand:
                if token == "-":
                    # Unary minus, treat as 0 - next_number
                    tokens.extend(["0", "-"])
                elif token == "+":
                    # Unary plus, can be ignored
                    pass
                else:
                    raise ValueError(f"Unexpected operator '{token}'")
            else:
                tokens.append(token)
                expect_operand = True
        elif token == "(":
            tokens.append(token)
            expect_operand = True
        elif token == ")":
            tokens.append(token)
            expect_operand = False
        else:  # It's a number
            tokens.append(token)
            expect_operand = False
        i += 1

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        val = tokens[pos]
        pos += 1
        return val

    def parse_factor():
        token = peek()
        if token == "(":
            consume()  # consume '('
            node = parse_expression()
            if peek() == ")":
                consume()  # consume ')'
            else:
                raise ValueError("Mismatched parentheses")
            return node
        elif token is not None:
            consume()
            return float(token) if "." in token else int(token)
        else:
            raise ValueError("Unexpected end of expression")

    def parse_term():
        node = parse_factor()
        while peek() in ("*", "/"):
            op = consume()
            right = parse_factor()
            if op == "*":
                node = node * right
            elif op == "/":
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                # Perform division. If both are ints and result is whole, return int
                if isinstance(node, int) and isinstance(right, int) and node % right == 0:
                    node = node // right
                else:
                    node = node / right
        return node

    def parse_expression():
        node = parse_term()
        while peek() in ("+", "-"):
            op = consume()
            right = parse_term()
            if op == "+":
                node = node + right
            elif op == "-":
                node = node - right
        return node

    result = parse_expression()

    if pos < len(tokens):
        raise ValueError("Unexpected tokens at the end of expression")

    return result
